//! Finnish postpositions, which take possessive suffixes (`alla`, `allani`): 6 declensions learned from 41 dictionary words, the rules on a
//! word's ending that choose one, and the forms no declension gives.
//!
//! Generated by flexion-train from Wiktionary; don't edit by hand.

mod irregular;
mod laws;
mod paradigms;
mod relations;
mod rules;
mod spellings;
mod stems;

pub use paradigms::Declension;

use flexion::{Candidate, Grammar, Known, Reading};
use std::borrow::Cow;

/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const POSTPOSITION_PLAIN: u16 = 0;
    pub const POSTPOSITION_1SG: u16 = 1;
    pub const POSTPOSITION_2SG: u16 = 2;
    pub const POSTPOSITION_1PL: u16 = 3;
    pub const POSTPOSITION_2PL: u16 = 4;
    pub const POSTPOSITION_3: u16 = 5;
}

/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Declension> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 6,
    lemma_cell: Some(0),
    capitalized: false,
    paradigms: Cow::Borrowed(&paradigms::DECLENSIONS),
    paradigm: rules::DECLENSION,
    relations: Cow::Borrowed(&relations::RELATIONS),
    feature: None,
    compound: None,
    kept: Cow::Borrowed(&[]),
    prefixes: None,
    heads: flexion::Heads {
        least: None,
        not: Cow::Borrowed(&[]),
        words: Cow::Borrowed(&[]),
    },
    accent: None,
    laws: Some(laws::LAWS),
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    marks: None,
    slots: Cow::Borrowed(&stems::SLOTS),
    tables: Cow::Borrowed(&stems::TABLES),
    irregular: irregular::IRREGULAR,
    smoothing: 2.0,
    sharpness: 0.5,
    trust: flexion::Trust {
        regular: 1.0,
        unsettled: 1.0,
        unattested: 1.0,
    },
};

/// A postposition form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A postposition, plain or with a possessive suffix.
    Form(crate::Suffix),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        use crate::Suffix::*;
        let cell = match self {
            Cell::Form(Plain) => cell::POSTPOSITION_PLAIN,
            Cell::Form(FirstSingular) => cell::POSTPOSITION_1SG,
            Cell::Form(SecondSingular) => cell::POSTPOSITION_2SG,
            Cell::Form(FirstPlural) => cell::POSTPOSITION_1PL,
            Cell::Form(SecondPlural) => cell::POSTPOSITION_2PL,
            Cell::Form(Third) => cell::POSTPOSITION_3,
        };
        cell as usize
    }
}

impl From<crate::Suffix> for Cell {
    fn from(suffix: crate::Suffix) -> Self {
        Cell::Form(suffix)
    }
}

/// A postposition to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Postposition<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Postposition<'w> {
    /// The postposition `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Postposition {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
